/**
 * Catalog lifecycle helpers — HAND-WRITTEN.
 *
 * Never put helpers in generated files: lib/catalog/products/index.ts and
 * the rec-*.ts records are regenerated by scripts/port-catalog.mjs, so
 * anything hand-written there would be silently overwritten on re-port.
 *
 * The canonical catalog marks retired products in their data
 * (verification_status: 'SUPERSEDED' + superseded_by: <handle>) rather
 * than deleting them — the record, its provenance, and its image-registry
 * entries stay for reference. Every storefront surface (checkout, product
 * page, sitemap, search) must consult this predicate so a superseded
 * product can never be sold, priced, indexed, or discovered as if it
 * were current.
 */
import type { Product } from '../../types';

/**
 * True ⇔ the product's record marks it SUPERSEDED. Exact, case-sensitive
 * match against the data value — the canonical records carry the
 * uppercase vocabulary declared in types/index.ts (VerificationStatus).
 */
export function isSupersededProduct(product: Product): boolean {
  return product.verification_status === 'SUPERSEDED';
}
